import java.util.*;

class Solution {
  public int connectSticks(int[] sticks) {
    PriorityQueue<Integer> pq = new PriorityQueue<>();
    for (int s : sticks) pq.add(s);
    int cost = 0;
    while (pq.size() > 1) {
      int joined = pq.poll() + pq.poll();
      cost += joined;
      pq.add(joined);
    }
    return cost;
  }
}
